package users

func Greeting(id int) (string, error) {
	u, err := FetchUser(id)
	if err != nil {
		return "", err
	}
	return "hi " + u.Email, nil
}

func Exists(id int) bool {
	_, err := FetchUser(id)
	return err == nil
}
EOF
